def tidy_existing_templates(apps, schema_editor):
    """Make existing rows satisfy the new one-live / one-draft rules without deleting anything.

    Before the editor existed a programme could in theory hold several live templates. Keep the
    newest as live and retire the others (their checklists keep pointing at them, so nothing
    already signed changes). Any stray unpublished rows are marked discarded the same way.
    """
    Template = apps.get_model("induction", "ChecklistTemplate")
    now = timezone.now()
    for program_id in Template.objects.values_list("program_id", flat=True).distinct():
        live = list(Template.objects.filter(program_id=program_id, published_at__isnull=False, retired_at__isnull=True).order_by("-version"))
        for old in live[1:]:
            Template.objects.filter(pk=old.pk).update(retired_at=now)
        drafts = list(Template.objects.filter(program_id=program_id, published_at__isnull=True, retired_at__isnull=True).order_by("-version"))
        for old in drafts[1:]:
            Template.objects.filter(pk=old.pk).update(retired_at=now)


